    snapshots: [expectedSnapshot],
    anchors: [[DEVICE_ID, START_TIME]],
    healthReports: [
      { account: healthyAccount, byDevice: new Map([[DEVICE_ID, healthyDevice]]) },
      { account: healthyAccount, byDevice: new Map([[DEVICE_ID, healthyDevice]]) },
      { account: haltedAccount, byDevice: new Map([[DEVICE_ID, haltedDevice]]) },
    ],
  };

  // act
  await runtime.start();
