        { restDegraded: false, shadowSilent: true, commandTransportReady: false, credentialsRejected: false },
        new Map([[DEVICE_ID, { restDegraded: false, shadowSilent: false, commandTransportReady: false, credentialsRejected: false }]]),
      );
