  assert.deepStrictEqual(credentialEvents, [
    ['register', 'test-access-key-id', 'aws-access-key-id'],
    ['register', 'test-secret-access-key', 'aws-secret-access-key'],
    ['register', 'test-session-token', 'aws-session-token'],
