    when(() => requests.awsCredentials(rootSignal)).thenResolve(unreadable);
    when(() => requests.awsCredentials(rootSignal)).thenResolve(unreadable);

    await runtime.start();
    await settle();

    // act
    await advance(SHORT_ROTATION_FLOOR_MS);

    // assert
    assert.strictEqual(calls.filter((call) => call === 'credentials').length, 2);
    assert.deepStrictEqual(commandRequests, []);
