    }).thenReturn(undefined);
    when(() => {
      registerSecret('test-session-token', 'aws-session-token');
    }).thenReturn(undefined);

    function silent(): void {
      return undefined;
    }

    const log: RedactingLogger = Object.assign(silent, {
      prefix: '',
      debug: silent,
      error: silent,
      info: silent,
      success: silent,
      warn: silent,
      log: silent,
