    const { runtime, anchors, shadows, monitoringByDevice, advance, commandRequests } = harness(
      t,
      { anchors: recordingAnchors([[DEVICE_ID, START_TIME - TWO_MISSED_HEARTBEATS_MS]]), command: commands },
