    await settle();
    const afterStart = {
      reports: monitoringByDevice.length,
      silent: monitoringByDevice.at(0)?.get(DEVICE_ID)?.shadowSilent,
      anchor: anchors.get(DEVICE_ID),
      stored: [...anchors.stored],
    };
