  }).thenReturn(undefined);
  when(() => {
    registerSecret('test-session-token', 'aws-session-token');
  }).thenReturn(undefined);
  when(() => {
    registerSecret('test-next-access-key-id', 'aws-access-key-id');
  }).thenReturn(undefined);
  when(() => {
    registerSecret('test-next-secret-access-key', 'aws-secret-access-key');
  }).thenReturn(undefined);
