  test('SYNC-05 arms no timer that outlives it', async (t) => {
    // arrange
    const requests = mock<Pick<CloudApi, 'devices' | 'awsCredentials'>>({ exactParams: true, name: 'scheduled vendor requests' });
    let rootSignal!: AbortSignal;

