    await runtime.stop();
    await advance(ONE_HOUR_MS);

    // assert
    assert.deepStrictEqual({ callsBeforeStop, callsAfterStop: calls.length }, { callsBeforeStop: 3, callsAfterStop: 3 });
    assert.deepStrictEqual(commandRequests, []);
