    when(() => {
      failures.forget(`HomeKit removal of ${DEVICE_ID}`);
    }).thenReturn(undefined);
    const reporting: FailureLog = {
      recordSuccess: (kind) => {
        failures.recordSuccess(kind);
        notifications.push(['success', kind]);
