        command: commands,
      },
      reporting,
      { onDeviceRemoved: removals },
    );
    await runtime.start();
    await settle();
    // Two missed heartbeats, so the pump's live reporting is failing when it goes.
    await advance(TWO_MISSED_HEARTBEATS_MS);
    await advance(TWO_MISSED_HEARTBEATS_MS);
    const atRemoval = { removed: [...removed], stored: runtime.store.deviceIds() };

