      ['request', 'https://tenant.example.test/oauth/token', null],
      ['register', 'id-token-1', undefined],
      ['request', 'https://api.example.test/devices', 'Bearer id-token-1'],
      ['request', 'https://api.example.test/credentials/aws', 'Bearer id-token-1'],
