    assert.deepStrictEqual({ connections: shadows.length, shadowAttempt: shadows[0]?.options.retry.attempt }, { connections: 1, shadowAttempt: 0 });
    assert.deepStrictEqual(commandRequests, []);
    verify(commands);
  });
});

