    when(() => {
      listener(
        { restDegraded: false, shadowSilent: true, commandTransportReady: false, credentialsRejected: true },
        new Map([[DEVICE_ID, { restDegraded: false, shadowSilent: false, commandTransportReady: false, credentialsRejected: true }]]),
