      pending.reject(new Error('inventory failed'));
    },
    precedingInventories: [() => Promise.resolve([geminiDevice()]), () => Promise.resolve([]), () => Promise.resolve([])],
    expectedInventories: [[DEVICE_ID], [], []],
    healthyReports: 2,
    haltAtMs: 2_500,
  },
]) {
