    const commands = mock<CloudApi['sendCommand']>({ exactParams: true, name: 'command dispatch' });
    const failures = mock<FailureLog>({ exactParams: true, name: 'account failure notifications' });
    when(() => {
      failures.recordSuccess('Device polling');
