          ]),
          calls: ['devices', 'credentials', 'shadow', 'devices', 'devices', 'devices', 'devices', 'devices', 'devices'],
        },
      ],
      calls: ['devices', 'credentials', 'shadow', 'devices', 'devices', 'devices', 'devices', 'devices', 'devices'],
      trustworthyInventories: [[DEVICE_ID, OTHER_DEVICE_ID], [OTHER_DEVICE_ID], [OTHER_DEVICE_ID], [], [OTHER_DEVICE_ID]],
      commandRequests: [],
    },
  );
  verify(requests);
