        snapshots: [{ ...expectedOtherSnapshot, receivedAt: START_TIME + 4_000 }],
        anchors: [[OTHER_DEVICE_ID, START_TIME]],
        account: healthyAccount,
        byDevice: new Map([[OTHER_DEVICE_ID, healthyDevice]]),
        removed: [DEVICE_ID],
