        accessKeyId: 'test-next-access-key-id',
        secretAccessKey: 'test-next-secret-access-key',
        sessionToken: 'test-next-session-token',
      },
    ],
  ]);
  verify(registerSecret);
  verify(shadow);
  verify(commands);
});

