        if (url === 'https://api.example.test/credentials/aws') {
          return Promise.resolve(new Response(JSON.stringify(credentialsAt(START_TIME + ONE_HOUR_MS)), { status: 200 }));
        }

        throw new Error('no response is scripted for this route');
