        },
      },
    );
    when(() => requests.devices(rootSignal)).thenResolve([geminiDevice()]);
    when(() => requests.devices(rootSignal)).thenReject(new CloudRequestError('GET /devices failed with HTTP 503.', 503, 'GET /devices'));
    when(() => requests.devices(rootSignal)).thenResolve([geminiDevice()]);

    await runtime.start();
    await settle();

